string siteKey = Tama.Args.Get(args, "siteKey", "");
if (siteKey.Trim().Length == 0) throw new Exception("Give the site name (siteKey).");
double targetM = Tama.Args.Get(args, "elevationMetres", 0.0);
double targetFt = targetM / 0.3048;

var locs = doc.ProjectLocations.Cast<ProjectLocation>().Where(l => l.Name.Contains(siteKey)).ToList();
if (locs.Count != 1) throw new Exception("Expected exactly one site matching '" + siteKey + "', found " + locs.Count);
var loc = locs[0];

ProjectPosition pp = loc.GetProjectPosition(XYZ.Zero);
double beforeM = pp.Elevation * 0.3048;
double ew = pp.EastWest, ns = pp.NorthSouth, ang = pp.Angle;

pp.Elevation = targetFt;
loc.SetProjectPosition(XYZ.Zero, pp);

ProjectPosition after = loc.GetProjectPosition(XYZ.Zero);
return new {
  site = loc.Name,
  elevationBeforeM = beforeM,
  elevationAfterM = after.Elevation * 0.3048,
  eastWestUnchanged = Math.Abs(after.EastWest - ew) < 1e-9,
  northSouthUnchanged = Math.Abs(after.NorthSouth - ns) < 1e-9,
  angleUnchanged = Math.Abs(after.Angle - ang) < 1e-9
};
